import RNA, random, time, multiprocessing as mp
target = "......((.((..((..(...(.((.((....))))..)...(.((..((....))..))..)...).))..))))....................."
n=len(target)
base="AAAAAAGCAGCAAGCAAGAAAGAGCAGCGAAAGCGCAACAAAGACGAACGGAAACGAACGAACAAACAGCAAGCGCAAAAAAAAAAAAAAAAAAAAA"
flanks=[18,19,20,22,36,37,39,40,41,43,60,61,63,64,65,15,16,11,12,67,70,71]
def fold(s): return RNA.fold_compound(s).mfe()[0]
def dist(s): return RNA.bp_distance(fold(s), target)
def run(seedn):
    random.seed(seedn)
    cur=base; cur_d=dist(cur); best,best_d=cur,cur_d
    deadline=time.time()+25
    while time.time()<deadline and best_d>0:
        c=list(cur)
        for _ in range(random.choice([1,1,2])):
            if random.random()<0.6: i=random.choice(flanks)
            else: i=random.randrange(n)
            c[i]=random.choice('ACGU')
        c=''.join(c); d=dist(c)
        if d<cur_d or (d==cur_d and random.random()<0.5):
            cur,cur_d=c,d
            if d<best_d: best,best_d=c,d
    return best_d,best
if __name__=='__main__':
    with mp.Pool(40) as p:
        results=p.map(run, range(40))
    results.sort()
    for d,s in results[:3]: print(d,s)
